"use client"

import { useState, useRef } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Upload, X, Maximize } from "lucide-react"
import Image from "next/image"

const thumbnailSizes = [
  { width: 202, height: 120, label: "네이버", description: "202 x 120px" },
  { width: 600, height: 800, label: "봄툰", description: "600 x 800px" },
  { width: 960, height: 1392, label: "레진", description: "960 x 1392px" },
]

export default function ThumbnailSizePage() {
  const [images, setImages] = useState<(string | null)[]>([null, null, null])
  const fileInputRefs = [
    useRef<HTMLInputElement>(null),
    useRef<HTMLInputElement>(null),
    useRef<HTMLInputElement>(null),
  ]

  const handleImageUpload = (
    index: number,
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = e.target.files?.[0]
    if (file) {
      const reader = new FileReader()
      reader.onloadend = () => {
        const newImages = [...images]
        newImages[index] = reader.result as string
        setImages(newImages)
      }
      reader.readAsDataURL(file)
    }
  }

  const handleRemoveImage = (index: number) => {
    const newImages = [...images]
    newImages[index] = null
    setImages(newImages)
  }

  return (
    <div className="mx-auto max-w-6xl">
      <div className="mb-8">
        <h1 className="flex items-center gap-3 text-3xl font-bold tracking-tight text-foreground">
          <Maximize className="h-8 w-8 text-primary" />
          사이트별 썸네일 크기 확인
        </h1>
        <p className="mt-2 text-muted-foreground">
          다양한 플랫폼에서 사용되는 썸네일 크기를 미리 확인할 수 있습니다.
        </p>
      </div>

      <div className="grid gap-8">
        {thumbnailSizes.map((size, index) => (
          <Card key={index} className="border-border bg-card">
            <CardHeader>
              <CardTitle className="flex items-center justify-between text-card-foreground">
                <div>
                  <span className="text-primary">{size.label}</span>
                  <span className="ml-2 text-sm font-normal text-muted-foreground">
                    {size.width} x {size.height}px - {size.description}
                  </span>
                </div>
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div
                className="relative mx-auto flex items-center justify-center overflow-hidden rounded-lg border-2 border-dashed border-border bg-secondary transition-colors"
                style={{
                  width: "100%",
                  maxWidth: Math.min(size.width, 500),
                  aspectRatio: `${size.width}/${size.height}`,
                }}
              >
                {images[index] ? (
                  <>
                    <Image
                      src={images[index]!}
                      alt={`Thumbnail ${index + 1}`}
                      fill
                      className="object-cover"
                    />
                    <Button
                      variant="destructive"
                      size="icon"
                      className="absolute right-2 top-2 h-8 w-8"
                      onClick={() => handleRemoveImage(index)}
                    >
                      <X className="h-4 w-4" />
                    </Button>
                  </>
                ) : (
                  <div className="flex flex-col items-center gap-3 text-muted-foreground">
                    <input
                      ref={fileInputRefs[index]}
                      type="file"
                      accept="image/*"
                      onChange={(e) => handleImageUpload(index, e)}
                      className="hidden"
                    />
                    <Button
                      variant="outline"
                      onClick={() => fileInputRefs[index].current?.click()}
                      className="gap-2"
                    >
                      <Upload className="h-4 w-4" />
                      이미지 업로드
                    </Button>
                    <p className="text-sm">
                      {size.width} x {size.height}px
                    </p>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  )
}
